     <meta charset="UTF-8" />
     <meta name="viewport" content="width=device-width, initial-scale=1.0" />
     <title>Product Access Consent</title>
     <style>
       :root {
         color-scheme: light;
         --bg: #f3f6fb;
         --bg-accent: rgba(88, 98, 255, 0.14);
         --surface: rgba(255, 255, 255, 0.9);
         --surface-strong: #ffffff;
         --text: #162033;
         --muted: #5e6983;
         --border: rgba(22, 32, 51, 0.12);
         --primary: #4454ff;
         --primary-strong: #3142ef;
         --error: #b42318;
         --success: #136c45;
         --shadow: 0 24px 60px rgba(27, 39, 94, 0.16);
         --radius-xl: 28px;
         --radius-lg: 18px;
         --radius-md: 12px;
       }

       * {
         box-sizing: border-box;
       }

       html,
       body {
         margin: 0;
         min-height: 100%;
         font-family:
           Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont,
           "Segoe UI", sans-serif;
         background:
           radial-gradient(circle at top, var(--bg-accent), transparent 32%),
           linear-gradient(180deg, #fbfcff 0%, var(--bg) 100%);
         color: var(--text);
       }

       body {
         min-height: 100vh;
       }

       a {
         color: inherit;
       }

       .skip-link {
         position: absolute;
         left: 1rem;
         top: 1rem;
         padding: 0.75rem 1rem;
         border-radius: 999px;
         background: var(--surface-strong);
         color: var(--text);
         transform: translateY(-200%);
         transition: transform 0.2s ease;
         z-index: 10;
       }

       .skip-link:focus {
         transform: translateY(0);
       }

       .page-shell {
         width: min(100%, 72rem);
         margin: 0 auto;
         padding: 1.25rem;
       }

       .hero {
         min-height: 100vh;
         display: grid;
         place-items: center;
       }

       .card {
         width: min(100%, 32rem);
         padding: clamp(1.5rem, 4vw, 2.5rem);
         background: var(--surface);
         border: 1px solid var(--border);
         border-radius: var(--radius-xl);
         box-shadow: var(--shadow);
         backdrop-filter: blur(20px);
       }

       .eyebrow {
         display: inline-flex;
         align-items: center;
         gap: 0.5rem;
         margin-bottom: 1rem;
         padding: 0.4rem 0.75rem;
         border-radius: 999px;
         background: rgba(68, 84, 255, 0.1);
         color: var(--primary-strong);
         font-size: 0.875rem;
         font-weight: 600;
         letter-spacing: 0.01em;
       }

       h1 {
         margin: 0 0 0.75rem;
         font-size: clamp(2rem, 5vw, 2.75rem);
         line-height: 1.05;
       }

       .intro {
         margin: 0 0 1.75rem;
         color: var(--muted);
         font-size: 1rem;
         line-height: 1.6;
       }

       form {
         display: grid;
         gap: 1.25rem;
       }

       .form-field {
         padding: 1rem;
         border: 1px solid var(--border);
         border-radius: var(--radius-lg);
         background: var(--surface-strong);
       }

       .checkbox-row {
         display: grid;
         grid-template-columns: auto 1fr;
         gap: 0.875rem;
         align-items: start;
       }

       input[type="checkbox"] {
         width: 1.15rem;
         height: 1.15rem;
         margin: 0.2rem 0 0;
         accent-color: var(--primary);
       }

       label {
         font-size: 1rem;
         line-height: 1.5;
         font-weight: 600;
       }

       .required-mark {
         color: var(--error);
         margin-left: 0.2rem;
       }

       .helper-text,
       .error-text,
       .status {
         margin: 0.75rem 0 0;
         font-size: 0.95rem;
         line-height: 1.5;
       }

       .helper-text {
         color: var(--muted);
       }

       .error-text {
         color: var(--error);
       }

       .status {
         min-height: 1.5rem;
         color: var(--success);
         font-weight: 600;
       }

       .actions {
         display: flex;
       }

       .submit-button {
         appearance: none;
         border: 0;
         border-radius: 999px;
         padding: 0.95rem 1.35rem;
         background: linear-gradient(135deg, var(--primary) 0%, var(--primary-strong) 100%);
         color: #fff;
         font: inherit;
         font-weight: 700;
         cursor: pointer;
         box-shadow: 0 16px 32px rgba(68, 84, 255, 0.24);
         transition:
           transform 0.18s ease,
           box-shadow 0.18s ease,
           opacity 0.18s ease;
       }

       .submit-button:hover {
         transform: translateY(-1px);
         box-shadow: 0 20px 38px rgba(68, 84, 255, 0.28);
       }

       .submit-button:active {
         transform: translateY(0);
       }

       .skip-link:focus-visible,
       input[type="checkbox"]:focus-visible,
       .submit-button:focus-visible {
         outline: 3px solid #111827;
         outline-offset: 3px;
       }

       .form-field[data-invalid="true"] {
         border-color: rgba(180, 35, 24, 0.65);
         box-shadow: 0 0 0 4px rgba(180, 35, 24, 0.08);
       }

       @media (max-width: 480px) {
         .page-shell {
           padding: 0.75rem;
         }

         .card {
           border-radius: 22px;
         }

         .actions {
           display: block;
         }

         .submit-button {
           width: 100%;
         }
       }

       @media (prefers-reduced-motion: reduce) {
         *,
         *::before,
         *::after {
           scroll-behavior: auto !important;
           transition-duration: 0.01ms !important;
           animation-duration: 0.01ms !important;
           animation-iteration-count: 1 !important;
         }
       }

       @media (forced-colors: active) {
         .card,
         .form-field,
         .submit-button,
         .skip-link {
           border: 1px solid CanvasText;
           box-shadow: none;
         }

         .submit-button {
           background: ButtonFace;
           color: ButtonText;
         }

         .eyebrow {
           border: 1px solid CanvasText;
         }
       }
     </style>
   </head>
   <body>
     <a class="skip-link" href="#maincontent">Skip to main content</a>
     <div id="app"></div>

     <script>
       function PageShell(content) {
         return `
           <div class="page-shell">
             ${content}
           </div>
         `;
       }

       function HeroCard(content) {
         return `
           <main id="maincontent" class="hero" tabindex="-1">
             <section class="card" aria-labelledby="page-title">
               ${content}
             </section>
           </main>
         `;
       }

       function ConsentField() {
         return `
           <div class="form-field" data-invalid="false">
             <div class="checkbox-row">
               <input
                 id="consent"
                 name="consent"
                 type="checkbox"
                 required
                 aria-describedby="consent-help"
               />
               <label for="consent">
                 I agree to the Terms of Use<span class="required-mark" aria-hidden="true">*</span>
               </label>
             </div>
             <p id="consent-help" class="helper-text">
               Required to continue with your setup.
             </p>
             <p id="consent-error" class="error-text" hidden>
               Error: Please agree to the Terms of Use to continue.
             </p>
           </div>
         `;
       }

       function SubmitButton() {
         return `
           <div class="actions">
             <button class="submit-button" type="submit">Continue</button>
           </div>
         `;
       }

       function ConsentForm() {
         return `
           <form id="consent-form" novalidate>
             ${ConsentField()}
             ${SubmitButton()}
             <p id="form-status" class="status" aria-live="polite"></p>
           </form>
         `;
       }

       function App() {
         return PageShell(
           HeroCard(`
             <p class="eyebrow">Product onboarding</p>
             <h1 id="page-title">Confirm your access</h1>
             <p class="intro">
               Review the final consent step before continuing to your workspace.
             </p>
             ${ConsentForm()}
           `)
         );
       }

       document.getElementById("app").innerHTML = App();

       const form = document.getElementById("consent-form");
       const checkbox = document.getElementById("consent");
       const field = checkbox.closest(".form-field");
       const error = document.getElementById("consent-error");
       const status = document.getElementById("form-status");

       function showCheckboxError() {
         field.dataset.invalid = "true";
         checkbox.setAttribute("aria-invalid", "true");
         checkbox.setAttribute("aria-describedby", "consent-help consent-error");
         error.hidden = false;
       }

       function clearCheckboxError() {
         field.dataset.invalid = "false";
         checkbox.removeAttribute("aria-invalid");
         checkbox.setAttribute("aria-describedby", "consent-help");
         error.hidden = true;
       }

       checkbox.addEventListener("change", function () {
         if (checkbox.checked) {
           clearCheckboxError();
           status.textContent = "";
         }
       });

       form.addEventListener("submit", function (event) {
         event.preventDefault();

         if (!checkbox.checked) {
           showCheckboxError();
           status.textContent = "";
           checkbox.focus();
           return;
         }

         clearCheckboxError();
         status.textContent = "Consent recorded. You can continue.";
       });
     </script>
   </body>
 </html>

